"""Render the measured experiment report from immutable JSON results, never run inference."""
import argparse,json,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(path):return json.loads(path.read_text())
def table(items):
    lines=['| Model / cohort | N | Median km | Mean km | ≤25 km | ≤100 km | ≤200 km | ≤500 km | ≤750 km |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for name,m in items:
        lines.append('| '+name+' | '+str(m['n'])+' | '+f"{m['median_km']:.1f} | {m['mean_km']:.1f}"+' | '+' | '.join(f"{100*m.get('within_'+str(k)+'km',0):.2f}%" for k in [25,100,200,500,750])+' |')
    return '\n'.join(lines)
def main():
    p=argparse.ArgumentParser();p.add_argument('--run-root',type=Path,default=ROOT/'artifacts/geoclip-overnight');args=p.parse_args();run=args.run_root
    base=read(run/'baseline-comparison.json');base_test=read(run/'baseline-test.json');a=read(run/'supervised/metrics.json');b=read(run/'distilled/metrics.json');big=read(ROOT/'artifacts/geoclip-direct/models/metadata.json');decision=read(run/'deployment-selection.json')
    big['reference_bytes']=next(f['bytes'] for f in big['files'] if f['path']=='references.f32')
    big['onnx_bytes']=sum(f['bytes'] for f in big['files'] if f['path']!='references.f32')
    big['native_cpu_latency_ms']=read(ROOT/'artifacts/geoclip-direct/validation-report.json')['native_cpu_latency_ms']
    av=a['candidates'][a['method']];bv=b['candidates'][b['method']];gv=big['candidates'][big['method']]
    outcome='YES' if bv['val']['median_km']<min(av['val']['median_km'],base['validation']['median_km'])*.98 else 'NO'
    cache=read(run/'teacher-cache/index.json');data=read(run/'data-summary.json');bench=read(run/'teacher-benchmark.json');images=read(run/'game-image-report.json');grid=read(run/'grid-search.json')
    rows=read(run/'manifest.json');country_count=len({r['country'] for r in rows});seq_count=len({r['sequence'] for r in rows})
    lines=['# EuroGuessr V2 research report — 5–6 October 2026','', '## Outcome','',f'**Did GeoCLIP distillation improve the tiny model? {outcome}**','',f"This answer requires a 2% shared-validation median-error gain against both V1 and the matched supervised control, so a larger reference pool alone is not credited to distillation. Deployed Tiny: **{decision['tiny']}**. The separate optional image-only quantized GeoCLIP uses **{big['method']}**. No human win-rate claim is made.",'','## Comparable geographic evaluation','',table([('V1 / validation',base['validation']),('Supervised A / validation',av['val']),('Distilled B / validation',bv['val']),('8-bit GeoCLIP / validation',gv['val']),('V1 / fresh test',base_test['fresh_test']),('Supervised A / fresh test',av['test']),('Distilled B / fresh test',bv['test']),('8-bit GeoCLIP / fresh test',gv['test'])]),'', 'Lower errors are better. All methods were selected and the deployment decision saved **before** opening the fresh test. Test results are descriptive; they did not change retrieval parameters or promotion. Country accuracy was not implemented. The constant-location baselines are retained in the student metrics JSON.','', '## Data and measured compute','',f"- OSV-5M revision `{data['revision']}`, three source shards per archive split; {data['splits']['train']:,} train, {data['splits']['val']:,} validation, {data['fresh_test']} fresh test plus 180 legacy inspected test images. {country_count} countries and {seq_count:,} distinct sequences overall.",'- Sampling used country balance, distinct sequences, three-degree geographic validation blocks, and a minimum 25 km new-training/holdout buffer. An additional old-model training buffer removed 39 validation and 237 planned fresh test examples, giving a fairer V1 comparison. All 40 public game photographs remain legacy test-only.',f"- Teacher: pinned GeoCLIP 1.2.1 / CLIP ViT-L/14. Cold load {bench['cold_load_seconds']:.2f} s including initial model download. Best measured batch {bench['best_batch_size']}; normalized 512-dimensional embeddings; repeated inference identical; batch differences below 2.4e-7.",'- Batch throughput: '+', '.join(f"{r['batch_size']}: {r['seconds_per_image']:.4f} s/image, {r['peak_rss_mb']:.0f} MiB peak RSS, {r['cpu_utilization_percent']:.1f}% CPU" for r in bench['results'])+'.',f"- Teacher subset: {cache['completed_images']:,} country/cell-balanced training images; accumulated cache compute {cache['elapsed_seconds']/3600:.3f} h (excludes model loading and paused time). Actual cache interruption/resume was verified against the location-embedding fingerprint.",f"- Frozen head grid: {grid['candidates']}; selected {grid['selected_cells']} cells using validation only.",'- All scientific computation ran in the pinned Docker image on the laptop CPU, two threads per research process. No cloud/GPU compute. Background jobs affected timings; browser and native timings below are observations, not controlled hardware comparisons.','','## Students and deployment assets','', '| Model | Parameters | ONNX MiB | Reference MiB | Native CPU median / p95 ms | Method |','|---|---:|---:|---:|---:|---|']
    for name,m in [('Supervised A',a),('Distilled B',b),('8-bit GeoCLIP',big)]:
        latency=m.get('native_cpu_latency_ms',{});lines.append(f"| {name} | {m['parameters']:,} | {m['onnx_bytes']/1048576:.3f} | {m['reference_bytes']/1048576:.3f} | {latency.get('median',0):.1f} / {latency.get('p95',0):.1f} | {m['method']} |")
    lines+=['','V1 has 1,087,056 parameters; its original 314-image validation median was 834.7 km and already-inspected 180-image test median was 862.6 km. Those original cohorts are historical, not the comparable evaluation above. Its browser smoke timings ranged from 35–346 ms in different sessions.','']
    for name,m in [('supervised',a),('distilled',b)]:
        h=read(run/name/'history.json');stages=collections.defaultdict(list)
        for epoch in h:stages[epoch['stage']].append(epoch)
        stage_text='; '.join(f"{stage}: {len(v)} epochs, {max(e['elapsed_seconds'] for e in v):.1f} s" for stage,v in stages.items())
        audit=m['distillation']['validation_representation'];audit_text='not measured' if not audit else f"{audit['mean_cosine']:.6f} on {audit['n']} held-out validation examples"
        lines += [f"- **{name}**: {stage_text}; deployed checkpoint {m.get('selected_checkpoint','best.pt')} at epoch {m['best_epoch']}; normalized projected representation cosine to the full-precision teacher: {audit_text}. Supervised A's projection is untrained and its cosine is only a control."]
    lines+=['','The final spatial residual/SE block and output convolution were fine-tuned with fixed batch-normalization statistics. The distilled objective was 0.5 geographic CE + 0.2 temperature-scaled KL + 0.3 cosine loss, with teacher terms masked for uncached images. Both native and projected retrieval spaces, geographic head and offline location-gallery retrieval were evaluated on validation. Full candidate tables are in each `metrics.json`.','',f"The optional GeoCLIP download contains {big.get('download_bytes',big['onnx_bytes']+big['reference_bytes']):,} bytes plus small coordinate metadata. Precision: **{big['precision']}**. Constant dequantization uses FP32 matrix multiplication and consumes more browser memory than the stored 8-bit download. Five weight shards are at most 64 MiB each. The browser contains no CLIP text tower or location encoder: it searches {10857:,} precomputed European location embeddings.",'','## Browser and game verification','',f"- Forty player photos total {sum(i['bytes'] for i in images['images']):,} bytes. Highest available source long edge is 910 px; exports preserve source size and never upscale. The archive cannot supply genuine 1600 px images.",'- Pointer Events provide photo zoom 1–4× and map zoom 1–8×, midpoint-anchored pinch/pan, clamping, cancellation and no pinch-created guess. The next photograph alone is preloaded. Natural Earth supplies 100 tiered city labels with collision suppression.', '- Chrome computer-agent evidence and actual five-round downloads are saved in `docs/` and summarized in `VALIDATION.md`. Responsive testing at 390×844 is desktop emulation, not a physical-phone benchmark. No human research matches were collected.','', '## Failures and limitations','', '- Signed INT8 source initially failed native ONNX Runtime on `ConvInteger`. The unsigned dynamic-activation variant ran but exact-input Chrome/native audits found embedding cosine near 0.99 and geographic differences up to 320 km. A FP32 patch-only repair worsened differences to 1,564 km. Both were rejected. The selected 8-bit stored-weight / FP32 arithmetic variant passed actual Chrome/native checks: maximum embedding error below 5.1e-7, coordinate difference below 0.005 km, and bit-exact JPEG preprocessing for the audit photo. These are two backend audit inputs, not an accuracy benchmark.', '- Plain nginx served `.mjs` with the wrong MIME type and initially prevented the compiled game from initializing WASM. The committed Docker preview config fixes `.mjs` and `.wasm` MIME types; GitHub Pages already serves the vendor module as JavaScript.', '- Tiny distillation is capacity-limited and the student/reference pack can still make large geographic errors. GeoCLIP needs a substantial explicit download and browser memory; phone performance is unmeasured.', '- The public 40-image pack was inspected previously. It is suitable for gameplay and UI checks, not fresh performance claims. Future model improvements require a new test cohort rather than retuning against this one.','', '## Checkpoints, reproduction and reversal','', '- `checkpoints/current/` and Git tag `euroguessr-v1-baseline-2026-10-05` preserve V1.', '- `checkpoints/geoclip-v2/` preserves both students’ best and last weights, optimizer and RNG state, grid, histories, exact image hashes, pinned dataset revision and teacher/cache archives. Bundle checksums verify continuation inputs.', '- `checkpoints/geoclip-direct/` preserves direct-model validation/test and quantization comparisons. Public external weight shards plus hashes preserve the deployed direct predictor.', '- Exact Docker commands for teacher generation/resume, student training/resume, verified restore, export, publication and revert are in `RESEARCH_V2.md`. `training/geoclip_overnight.sh` reproduces the main research stages; final test and promotion are separate explicit steps.', '- Automated evidence includes eight Node checks, five distillation contract tests, numerically reproducible optimizer/model resume (1e-7 tolerance) and exact RNG restoration, expired-deadline export, wider-tail transition/parity, six exact CLIP preprocessing shapes, leakage/runtime fixtures, asset synchronization and full Docker Jekyll compilation. Final run results and browser scope are recorded in `VALIDATION.md`.','']
    (run/'REPORT.md').write_text('\n'.join(lines));print(run/'REPORT.md')
if __name__=='__main__':main()
